const { request, remaining, resetsAt } = $('Check limits').item.json;
const answer = $json.output ?? {};

/** Keeps the cook within the real number of cooks and allows parallel only where it can happen. */
function toStep(step, index, cooks) {
  const cook = Number.isInteger(step.cook) && step.cook >= 1 && step.cook <= cooks ? step.cook : 1;
  const parallel = cooks > 1 && index > 0 && step.parallel === true;
  return { order: index + 1, cook, title: step.title.trim(), text: step.text.trim(), parallel };
}

/** Turns one recipe from Gemini into the Recipe shape of the api contract, without id and likes. */
function toRecipe(raw) {
  const steps = [...raw.steps].sort((a, b) => a.order - b.order);
  return {
    title: raw.title.trim(),
    cookingTimeMinutes: raw.cookingTimeMinutes,
    cookingTime: request.cookingTime,
    cuisine: request.cuisine,
    diet: request.diet,
    portions: request.portions,
    cooks: request.cooks,
    nutrition: { perPortion: raw.nutrition },
    ingredients: { yours: raw.yours, extra: raw.extra.slice(0, 3) },
    steps: steps.map((step, index) => toStep(step, index, request.cooks)),
  };
}

if (answer.insufficient === true) {
  const message = answer.reason || 'The ingredients are not enough for the selected portions.';
  return { json: { outcome: 'insufficient', status: 422, error: { code: 'insufficient_ingredients', message } } };
}
if (!Array.isArray(answer.recipes) || answer.recipes.length !== 3) {
  return { json: { outcome: 'ai_error' } };
}
return { json: { outcome: 'recipes', recipes: answer.recipes.map(toRecipe), quota: { remaining, resetsAt } } };

const { recipes, quota } = $('Build result').first().json;
const saved = $input.all().map((item) => item.json);

const withIds = recipes.map((recipe, index) => ({ id: saved[index].id, ...recipe, likes: saved[index].likes }));

return [{ json: { recipes: withIds, quota } }];
